mapper.select:
select ACCT_NO, PORTFOLIO_ID, CCY, ACCT_TYPE from PTL_CAPACCT_INFO where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND ACCT_TYPE IN
#{item}

	select t.* from(
		select
			ACCT_NO, PORTFOLIO_ID, CCY, ACCT_TYPE, row_number() over() as rownum
		from
			PTL_CAPACCT_INFO
		where
			PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
			and CCY = #{ccy,jdbcType=VARCHAR}
            AND ACCT_TYPE  = #{acctType,jdbcType=VARCHAR}

    ) t where t.rownum = 1
